let response;

switch (action) {
  case 'list':
    response = { 
      continents: locationDatabase.continents, 
      regions: locationDatabase.regions, 
      dungeons: locationDatabase.dungeons 
    };
    break;
  case 'get':
    if (locationId) {
      const location = [...locationDatabase.continents, ...locationDatabase.regions, ...locationDatabase.dungeons]
        .find(loc => loc.id === locationId);
      response = location || { error: 'Location not found' };
    } else {
      response = { error: 'Location ID required' };
    }
    break;
  case 'create':
    const newLocation = {
      id: `location-${Date.now()}`,
      ...locationData,
      createdAt: new Date().toISOString()
    };
    response = { success: true, location: newLocation };
    break;
  case 'update':
    response = { success: true, message: 'Location updated successfully' };
    break;
  case 'search':
    const results = [...locationDatabase.continents, ...locationDatabase.regions, ...locationDatabase.dungeons]
      .filter(loc => {
        if (searchCriteria.name && !loc.name.toLowerCase().includes(searchCriteria.name.toLowerCase())) {
          return false;
        }
        if (searchCriteria.type && loc.type !== searchCriteria.type) {
          return false;
        }
        if (searchCriteria.climate && loc.climate !== searchCriteria.climate) {
          return false;
        }
        return true;
      });
    response = { locations: results, total: results.length };
    break;
  case 'getSettlements':
    if (regionId) {
      const region = locationDatabase.regions.find(r => r.id === regionId);
      response = region ? { settlements: region.settlements || [] } : { error: 'Region not found' };
    } else {
      response = { error: 'Region ID required' };
    }
    break;
  case 'getPointsOfInterest':
    if (regionId) {
      const region = locationDatabase.regions.find(r => r.id === regionId);
      response = region ? { pointsOfInterest: region.pointsOfInterest || [] } : { error: 'Region not found' };
    } else {
      response = { error: 'Region ID required' };
    }
    break;
  default:
    response = { error: 'Invalid action' };
}

return [{ json: response }];

