// Relationship mapping functions
const generateRelationshipMap = (npcId) => {
  const npc = npcDatabase.find(n => n.id === npcId);
  if (!npc) return { error: 'NPC not found' };

  const relationshipMap = {
    npc: {
      id: npc.id,
      name: npc.name,
      title: npc.title,
      location: npc.location
    },
    relationships: {
      allies: npc.relationships.allies || [],
      enemies: npc.relationships.enemies || [],
      neutral: npc.relationships.neutral || [],
      complicated: npc.relationships.complicated || [],
      romantic: npc.relationships.romantic || [],
      family: npc.relationships.allies?.filter(r => r.type === 'family') || []
    },
    networkAnalysis: {
      totalConnections: 0,
      strongestBond: null,
      mostDangerousEnemy: null,
      potentialAllies: [],
      conflictingLoyalties: []
    }
  };

  // Calculate network metrics
  const allRelationships = Object.values(relationshipMap.relationships).flat();
  relationshipMap.networkAnalysis.totalConnections = allRelationships.length;

  // Find strongest bond
  const allies = relationshipMap.relationships.allies;
  if (allies.length > 0) {
    relationshipMap.networkAnalysis.strongestBond = allies.reduce((strongest, current) => 
      (current.relationship?.includes('Close') || current.relationship?.includes('Best')) ? current : strongest
    );
  }

  // Find most dangerous enemy
  const enemies = relationshipMap.relationships.enemies;
  if (enemies.length > 0) {
    relationshipMap.networkAnalysis.mostDangerousEnemy = enemies.reduce((mostDangerous, current) => 
      (current.relationship?.includes('Arch') || current.relationship?.includes('Personal')) ? current : mostDangerous
    );
  }

  return relationshipMap;
};

const findRelationshipPaths = (startNpc, endNpc) => {
  const paths = [];
  const visited = new Set();

  const findPath = (currentId, targetId, path = []) => {
    if (visited.has(currentId)) return;
    if (path.length > 3) return; // Limit path length

    visited.add(currentId);
    const currentPath = [...path, currentId];

    if (currentId === targetId) {
      paths.push(currentPath);
      visited.delete(currentId);
      return;
    }

    const currentNpc = npcDatabase.find(n => n.id === currentId);
    if (!currentNpc) {
      visited.delete(currentId);
      return;
    }

    const connections = Object.values(currentNpc.relationships).flat();
    for (const connection of connections) {
      findPath(connection.id, targetId, currentPath);
    }

    visited.delete(currentId);
  };

  findPath(startNpc, endNpc);
  return paths;
};

let response;

switch (action) {
  case 'list':
    response = { npcs: npcDatabase, total: npcDatabase.length };
    break;
  case 'get':
    const npc = npcDatabase.find(n => n.id === npcId);
    response = npc || { error: 'NPC not found' };
    break;
  case 'getRelationships':
    response = generateRelationshipMap(npcId);
    break;
  case 'findPath':
    const { startNpc, endNpc } = $input.first().json.body;
    const paths = findRelationshipPaths(startNpc, endNpc);
    response = { paths, pathCount: paths.length };
    break;
  case 'search':
    const results = npcDatabase.filter(npc => {
      if (searchCriteria.name && !npc.name.toLowerCase().includes(searchCriteria.name.toLowerCase())) {
        return false;
      }
      if (searchCriteria.race && npc.race !== searchCriteria.race) {
        return false;
      }
      if (searchCriteria.class && npc.class !== searchCriteria.class) {
        return false;
      }
      if (searchCriteria.location && npc.location !== searchCriteria.location) {
        return false;
      }
      if (searchCriteria.alignment && npc.alignment !== searchCriteria.alignment) {
        return false;
      }
      return true;
    });
    response = { npcs: results, total: results.length };
    break;
  case 'create':
    const newNpc = {
      id: `npc-${Date.now()}`,
      ...npcData,
      createdAt: new Date().toISOString()
    };
    response = { success: true, npc: newNpc };
    break;
  case 'update':
    response = { success: true, message: 'NPC updated successfully' };
    break;
  default:
    response = { error: 'Invalid action' };
}

return [{ json: response }];

