// Faction relationship analysis
const analyzeFactionRelationships = (factionId) => {
  const faction = factionDatabase.find(f => f.id === factionId);
  if (!faction) return { error: 'Faction not found' };

  const analysis = {
    faction: {
      id: faction.id,
      name: faction.name,
      type: faction.type,
      alignment: faction.alignment
    },
    diplomaticStatus: {
      totalRelations: 0,
      allies: 0,
      enemies: 0,
      neutral: 0,
      complicated: 0,
      mostPowerfulAlly: null,
      greatestThreat: null,
      unstableRelations: []
    },
    militaryAssessment: {
      totalStrength: faction.military?.totalForces || 0,
      quality: 'professional',
      specialCapabilities: faction.military?.specialForces || [],
      readiness: 'high',
      weaknesses: []
    },
    economicStatus: {
      stability: 'stable',
      tradeRoutes: 'secure',
      resources: 'adequate',
      vulnerabilities: []
    },
    politicalStability: {
      internal: faction.internalPolitics?.stability || 'unknown',
      leadership: 'secure',
      succession: 'planned',
      threats: faction.internalPolitics?.conflicts || []
    }
  };

  // Calculate diplomatic metrics
  const allRelations = Object.values(faction.relationships).flat();
  analysis.diplomaticStatus.totalRelations = allRelations.length;
  analysis.diplomaticStatus.allies = faction.relationships.allies?.length || 0;
  analysis.diplomaticStatus.enemies = faction.relationships.enemies?.length || 0;
  analysis.diplomaticStatus.neutral = faction.relationships.neutral?.length || 0;
  analysis.diplomaticStatus.complicated = faction.relationships.complicated?.length || 0;

  // Identify most powerful ally
  if (faction.relationships.allies && faction.relationships.allies.length > 0) {
    analysis.diplomaticStatus.mostPowerfulAlly = faction.relationships.allies[0];
  }

  // Identify greatest threat
  if (faction.relationships.enemies && faction.relationships.enemies.length > 0) {
    analysis.diplomaticStatus.greatestThreat = faction.relationships.enemies.find(e => 
      e.relationship?.includes('Existential') || e.relationship?.includes('Major')
    ) || faction.relationships.enemies[0];
  }

  return analysis;
};

