      resolution: 'Conversion, suppression, or accommodation',
      participants: ['All factions', 'Religious leaders'],
      duration: 'Generations'
    }
  ];

  // Select appropriate scenario based on faction types and alignments
  let selectedScenario;

  if (faction1.alignment.includes('Evil') || faction2.alignment.includes('Evil')) {
    selectedScenario = scenarios.find(s => s.type === 'resource_war') || scenarios[2];
