// Timeline analysis functions
const analyzeTimelinePeriod = (timelineId, startYear, endYear) => {
  const timeline = timelineDatabase[timelineId];
  if (!timeline) return { error: 'Timeline not found' };

  const events = timeline.events || [];
  if (timeline.eras) {
    timeline.eras.forEach(era => {
      events.push(...era.majorEvents);
    });
  }

  const periodEvents = events.filter(event => {
    const eventYear = event.year || event.date?.year || 0;
    return eventYear >= startYear && eventYear <= endYear;
  });

  const analysis = {
    period: {
      startYear,
      endYear,
      duration: endYear - startYear
    },
    eventSummary: {
      total: periodEvents.length,
      byType: {},
      byImportance: { critical: 0, major: 0, minor: 0, current: 0 },
      averageEventsPerYear: (periodEvents.length / (endYear - startYear + 1)).toFixed(2)
    },
    significantEvents: periodEvents.filter(e => e.importance === 'critical'),
    patterns: {
      wars: periodEvents.filter(e => e.type === 'war').length,
      invasions: periodEvents.filter(e => e.type === 'invasion').length,
      catastrophes: periodEvents.filter(e => e.type === 'cataclysm').length,
      discoveries: periodEvents.filter(e => e.type === 'discovery').length,
      political: periodEvents.filter(e => e.type === 'political').length
n    },
    narrativeArcs: []
  };

  // Categorize events by type
  periodEvents.forEach(event => {
    const type = event.type || 'unknown';
    analysis.eventSummary.byType[type] = (analysis.eventSummary.byType[type] || 0) + 1;

    const importance = event.importance || 'minor';
    analysis.eventSummary.byImportance[importance] = (analysis.eventSummary.byImportance[importance] || 0) + 1;
  });

  // Identify narrative arcs
  const warPeriods = periodEvents.filter(e => e.type === 'war' || e.type === 'invasion');
  if (warPeriods.length >= 2) {
    analysis.narrativeArcs.push({
      type: 'conflict',
      name: 'Period of Conflict',
      events: warPeriods,
      description: 'Time marked by warfare and invasion'
    });
  }

  const politicalEvents = periodEvents.filter(e => e.type === 'political');
  if (politicalEvents.length >= 3) {
    analysis.narrativeArcs.push({
      type: 'political',
      name: 'Political Upheaval',
      events: politicalEvents,
      description: 'Period of significant political change'
    });
  }

  return analysis;
};

const generateFutureEvents = (timelineId, yearsAhead = 5) => {
  const timeline = timelineDatabase[timelineId];
  if (!timeline) return { error: 'Timeline not found' };

  const currentYear = timeline.currentYear || timelineDatabase.campaignTimeline.currentYear;
  const futureEvents = [];

  const eventTemplates = [
    {
      type: 'political',
      likelihood: 0.3,
      templates: [
        'Treaty signed between rival kingdoms',
        'Royal succession crisis',
        'Revolution in major city',
        'Alliance formation',
        'Trade embargo declared'
      ]
    },
    {
      type: 'conflict',
      likelihood: 0.4,
      templates: [
        'Border skirmish escalates',
        'Rebellion suppressed',
        'Mercenary company hired',
        'Pirate activity increases',
        'Monster attacks on trade routes'
      ]
    },
    {
      type: 'magical',
      likelihood: 0.2,
      templates: [
        'Ancient magical artifact discovered',
        'Magical plague spreads',
        'Portal to another plane opens',
        'Dragon sighting reported',
        'Magical experiment goes wrong'
      ]
    },
    {
      type: 'natural',
      likelihood: 0.15,
      templates: [
        'Volcanic eruption threatens region',
        'Earthquake destroys city',
        'Magical storm appears',
        'Plague of magical creatures',
        'Unusual weather patterns'
      ]
    },
    {
      type: 'discovery',
      likelihood: 0.25,
      templates: [
        'Lost civilization found',
        'Underground complex discovered',
        'Ancient prophecy revealed',
        'New trade route established',
        'Rare resources found'
      ]
    }
  ];

  for (let year = 1; year <= yearsAhead; year++) {
    const eventYear = currentYear + year;
    const eventsInYear = [];

    // Generate 1-3 events per year
    const numEvents = Math.floor(Math.random() * 3) + 1;

    for (let i = 0; i < numEvents; i++) {
      const eventType = eventTemplates.find(t => Math.random() < t.likelihood) || eventTemplates[0];
      const template = eventType.templates[Math.floor(Math.random() * eventType.templates.length)];

      const importance = Math.random() < 0.1 ? 'critical' : Math.random() < 0.3 ? 'major' : 'minor';

      const event = {
        id: `future-${year}-${i}`,
        name: template,
        date: {
          year: eventYear,
          month: Math.floor(Math.random() * 12) + 1,
          day: Math.floor(Math.random() * 28) + 1
        },
        type: eventType.type,
        importance,
        description: `Future event: ${template}`,
        likelihood: Math.random(),
        preventable: eventType.type !== 'natural',
        potentialImpact: importance === 'critical' ? 'Campaign-changing' : importance === 'major' ? 'Significant' : 'Minor'
      };

      eventsInYear.push(event);
    }

    futureEvents.push({
      year: eventYear,
      events: eventsInYear,
      yearSummary: `${eventsInYear.length} potential events scheduled`
    });
  }

  return {
    futureEvents,
    summary: {
      totalEvents: futureEvents.reduce((sum, year) => sum + year.events.length, 0),
      criticalEvents: futureEvents.reduce((sum, year) => 
        sum + year.events.filter(e => e.importance === 'critical').length, 0),
      preventableEvents: futureEvents.reduce((sum, year) => 
        sum + year.events.filter(e => e.preventable).length, 0)
    }
  };
};

let response;

switch (action) {
  case 'list':
    response = { timelines: Object.keys(timelineDatabase), details: timelineDatabase };
    break;
  case 'get':
    response = timelineDatabase[timelineId] || { error: 'Timeline not found' };
    break;
  case 'analyze':
    const { startYear, endYear } = $input.first().json.body;
    response = analyzeTimelinePeriod(timelineId, startYear, endYear);
    break;
  case 'future':
    const { yearsAhead } = $input.first().json.body;
    response = generateFutureEvents(timelineId, yearsAhead);
    break;
  case 'search':
    const allEvents = [];
    Object.values(timelineDatabase).forEach(timeline => {
      if (timeline.events) allEvents.push(...timeline.events);
      if (timeline.eras) {
        timeline.eras.forEach(era => {
          if (era.majorEvents) allEvents.push(...era.majorEvents);
        });
      }
    });

    const results = allEvents.filter(event => {
      if (searchCriteria.type && event.type !== searchCriteria.type) return false;
      if (searchCriteria.importance && event.importance !== searchCriteria.importance) return false;
      if (searchCriteria.yearRange) {
        const eventYear = event.year || event.date?.year || 0;
        if (eventYear < searchCriteria.yearRange.start || eventYear > searchCriteria.yearRange.end) return false;
      }
      if (searchCriteria.keyword && !event.name.toLowerCase().includes(searchCriteria.keyword.toLowerCase())) return false;
      return true;
    });

    response = { events: results, total: results.length };
    break;
  case 'create':
    const newEvent = {
      id: `event-${Date.now()}`,
      ...eventData,
      createdAt: new Date().toISOString()
    };
    response = { success: true, event: newEvent };
    break;
  case 'update':
    response = { success: true, message: 'Event updated successfully' };
    break;
  default:
    response = { error: 'Invalid action' };
}

return [{ json: response }];

