// Map analysis functions
const calculateDistances = (mapId, point1, point2) => {
  const map = mapDatabase[mapId];
  if (!map) return { error: 'Map not found' };

  const dx = point2.x - point1.x;
  const dy = point2.y - point1.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  // Convert to actual distance based on map scale
  const scaleMatch = map.scale.match(/1:(\d+)/);
  const scale = scaleMatch ? parseInt(scaleMatch[1]) : 1000;
  const actualDistance = distance * scale / 5280; // Convert to miles if needed

  return {
    distance: distance.toFixed(2),
    actualDistance: actualDistance.toFixed(2),
    unit: 'miles',
    direction: {
      bearing: Math.atan2(dy, dx) * 180 / Math.PI,
      cardinal: getCardinalDirection(dx, dy)
    },
    travelTime: {
      walking: `${Math.round(actualDistance / 3)} hours`,
      riding: `${Math.round(actualDistance / 8)} hours`,
      flying: `${Math.round(actualDistance / 20)} hours`
    }
  };
};

const getCardinalDirection = (dx, dy) => {
  const angle = Math.atan2(dy, dx) * 180 / Math.PI;

  if (angle >= -22.5 && angle < 22.5) return 'East';
  if (angle >= 22.5 && angle < 67.5) return 'Southeast';
  if (angle >= 67.5 && angle < 112.5) return 'South';
  if (angle >= 112.5 && angle < 157.5) return 'Southwest';
  if (angle >= 157.5 || angle < -157.5) return 'West';
  if (angle >= -157.5 && angle < -112.5) return 'Northwest';
  if (angle >= -112.5 && angle < -67.5) return 'North';
  if (angle >= -67.5 && angle < -22.5) return 'Northeast';
  return 'East';
};

const findNearbyLocations = (mapId, centerPoint, radius) => {
  const map = mapDatabase[mapId];
  if (!map) return { error: 'Map not found' };

  const nearbyLocations = [];

  // Check all locations on the map
  const checkLocations = (locations, type = 'location') => {
    if (!locations) return;

    locations.forEach(location => {
      const distance = calculateDistances(mapId, centerPoint, location.location || { x: location.x, y: location.y });
      if (parseFloat(distance.actualDistance) <= radius) {
        nearbyLocations.push({
          ...location,
          type,
          distance: distance.actualDistance,
          direction: distance.direction.cardinal
        });
      }
    });
  };

  // Check different types of locations
  if (map.continents) {
    map.continents.forEach(continent => {
      checkLocations(continent.capitals, 'capital');
      checkLocations(continent.geographicalFeatures, 'geographical');
    });
  }

  if (map.districts) {
    checkLocations(map.districts, 'district');
  }

  if (map.areas) {
    checkLocations(map.areas, 'area');
  }

  return {
    center: centerPoint,
    radius,
    locations: nearbyLocations.sort((a, b) => parseFloat(a.distance) - parseFloat(b.distance)),
    totalFound: nearbyLocations.length
  };
};

const generateRoute = (mapId, startPoint, endPoint, preferences = {}) => {
  const map = mapDatabase[mapId];
  if (!map) return { error: 'Map not found' };

  const distance = calculateDistances(mapId, startPoint, endPoint);

  // Generate route based on preferences
  const route = {
    start: startPoint,
    end: endPoint,
    totalDistance: distance.actualDistance,
    estimatedTime: preferences.mode === 'fast' ? distance.travelTime.flying : 
                     preferences.mode === 'mounted' ? distance.travelTime.riding : 
                     distance.travelTime.walking,
    waypoints: [],
    hazards: [],
    pointsOfInterest: []
  };

  // Add waypoints based on terrain and features
  if (map.continents) {
    map.continents.forEach(continent => {
      // Check if route crosses major geographical features
      continent.geographicalFeatures?.forEach(feature => {
        if (isNearRoute(startPoint, endPoint, feature.location || { x: feature.x, y: feature.y }, 0.5)) {
          route.waypoints.push({
            name: feature.name,
            type: 'geographical',
            description: `Pass near ${feature.name}`,
            location: feature.location || { x: feature.x, y: feature.y }
          });
        }
      });
    });
  }

  // Add travel hazards based on map type
  if (map.type === 'world') {
    route.hazards = [
      'Random encounters possible',
      'Weather conditions may affect travel',
      'Terrain difficulties in certain areas'
    ];
  } else if (map.type === 'dungeon') {
    route.hazards = map.hazards || [];
  }

  return route;
};

const isNearRoute = (start, end, point, threshold) => {
  // Simple check if point is near the line between start and end
  const lineDistance = Math.sqrt(Math.pow(end.x - start.x, 2) + Math.pow(end.y - start.y, 2));
  const dist1 = Math.sqrt(Math.pow(point.x - start.x, 2) + Math.pow(point.y - start.y, 2));
  const dist2 = Math.sqrt(Math.pow(end.x - point.x, 2) + Math.pow(end.y - point.y, 2));

  return Math.abs(dist1 + dist2 - lineDistance) < threshold;
};

let response;

switch (action) {
  case 'list':
    response = { maps: Object.keys(mapDatabase), details: mapDatabase };
    break;
  case 'get':
    response = mapDatabase[mapId] || { error: 'Map not found' };
    break;
  case 'distance':
    const { point1, point2 } = $input.first().json.body;
    response = calculateDistances(mapId, point1, point2);
    break;
  case 'nearby':
    const { centerPoint, radius } = $input.first().json.body;
    response = findNearbyLocations(mapId, centerPoint, radius);
    break;
  case 'route':
    const { startPoint, endPoint, preferences } = $input.first().json.body;
    response = generateRoute(mapId, startPoint, endPoint, preferences);
    break;
  case 'search':
    const results = Object.values(mapDatabase).filter(map => {
      if (searchCriteria.type && map.type !== searchCriteria.type) return false;
      if (searchCriteria.name && !map.name.toLowerCase().includes(searchCriteria.name.toLowerCase())) return false;
      if (searchCriteria.scale && !map.scale.includes(searchCriteria.scale)) return false;
      return true;
    });
    response = { maps: results, total: results.length };
    break;
  case 'create':
    const newMap = {
      id: `map-${Date.now()}`,
      ...mapData,
      createdAt: new Date().toISOString()
    };
    response = { success: true, map: newMap };
    break;
  case 'update':
    response = { success: true, message: 'Map updated successfully' };
    break;
  default:
    response = { error: 'Invalid action' };
}

return [{ json: response }];
